1	// What each figure name in a rule's `when`, `and` or `floor` MEANS - the one place
2	// the review's vocabulary meets the record's. The evaluator knows the grammar and
3	// nothing else; this knows the counters and nothing about rules.
4	//
5	// Every reader here returns `null` for *not recorded* and a number otherwise,
6	// including 0. The distinction is the whole point: a week frozen before a counter
7	// existed carries no key, and reading that as zero would report a skill nobody
8	// could measure as a skill nobody used.
9	//
10	// The record is read off the fold file's OWN `fields` header, never a vocabulary
11	// imported from the pack that writes it: the file is a published artifact, and a
12	// consumer that imported the writer's code would break the day the two shipped
13	// apart. Same reason the dashboard reads it that way.
14	
15	// A day row's bare map, summed across the window for one key. `null` where no day
16	// in the window carried the map at all - which is the shape a counter has before
17	// the fold that writes it has run anywhere in the window.
18	function sumBare(days, map, key) {
19	  let total = null;
20	  for (const day of days) {
21	    const carried = day?.[map];
22	    if (!carried || typeof carried !== 'object') continue;
23	    total = (total ?? 0) + (carried[key] ?? 0);
24	  }
25	  return total;
26	}
27	
28	// …and a counter group's field under one key.
29	function sumGroup(days, group, key, field) {
30	  let total = null;
31	  for (const day of days) {
32	    const row = day?.[group]?.[key];
33	    if (!row || typeof row !== 'object' || !(field in row)) continue;
34	    total = (total ?? 0) + (row[field] ?? 0);
35	  }
36	  return total;
37	}
38	
39	// A scalar the day row carries in its own right.
40	function sumScalar(days, field) {
41	  let total = null;
42	  for (const day of days) {
43	    if (typeof day?.[field] !== 'number') continue;
44	    total = (total ?? 0) + day[field];
45	  }
46	  return total;
47	}
48	
49	// Every key of a group, summed - the scope totals, for the rules that judge the
50	// checks as a whole rather than one rule of them.
51	function sumEveryKey(days, group, field) {
52	  let total = null;
53	  for (const day of days) {
54	    for (const row of Object.values(day?.[group] ?? {})) {
55	      if (!row || !(field in row)) continue;
56	      total = (total ?? 0) + (row[field] ?? 0);
57	    }
58	  }
59	  return total;
60	}
61	
62	export function median(values) {
63	  const sorted = values.filter((v) => typeof v === 'number' && Number.isFinite(v)).sort((a, b) => a - b);
64	  if (!sorted.length) return null;
65	  const mid = sorted.length >> 1;
66	  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
67	}
68	
69	// What one Stop sweep cost, per day - the mean over that day's runs, which is what
70	// a median across the window is then taken of. A day whose sweeps left no timing
71	// record contributes nothing rather than a zero.
72	export function dailyStopMs(days) {
73	  const out = [];
74	  for (const day of days) {
75	    const row = day?.checkTiming?.work;
76	    if (!row || !(row.runs > 0) || typeof row.totalMs !== 'number') continue;
77	    out.push(row.totalMs / row.runs);
78	  }
79	  return out;
80	}
81	
82	// HOW BUSY THE REPOSITORY WAS, as one number - the denominator every rule's
83	// "is there enough here to judge" floor is read against.
84	//
85	// No single counter answers it. A window can carry many prompts and no merges, or
86	// many merges and few prompts, and a floor reading either one alone calls the other
87	// kind of week quiet. So four counters answer it together, each approaching the
88	// same question from a different side: what the owner asked for, what the
89	// conversation cost, what shipped, and what closed.
90	//
91	// `per` is the unit that puts a term on the same scale as the others, so a typical
92	// window contributes comparably from each. The WEIGHTS are then the only bias in
93	// the blend, and they are deliberately uneven: a person's own prompts are the most
94	// direct evidence that work happened here, so they carry the most. Both halves are
95	// cheap to re-examine from the record, and the retrospective brief says so.
96	//
97	// `tokensOut` rather than `tokensIn`: input is dominated by cache reads (fifteen
98	// billion against forty-eight million in the window this was chosen from), so it
99	// measures the harness's caching far more than it measures the work.
100	export const ACTIVITY_TERMS = Object.freeze({
101	  userMessages: Object.freeze({ weight: 0.4, per: 1 }),
102	  tokensOut: Object.freeze({ weight: 0.2, per: 100_000 }),
103	  merges: Object.freeze({ weight: 0.2, per: 1 }),
104	  itemsClosed: Object.freeze({ weight: 0.2, per: 1 }),
105	});
106	
107	// The blend, given a reader for one term's window total. A term the record does not
108	// carry is DROPPED and the remaining weights re-normalized over what was recorded -
109	// never counted as a zero, which would report a window nobody could measure as a
110	// window in which nothing happened. No term recorded at all is `null`, and a term
111	// that really is zero still counts as zero.
112	export function activityOf(readTerm) {
113	  let weighted = 0;
114	  let covered = 0;
115	  for (const [name, { weight, per }] of Object.entries(ACTIVITY_TERMS)) {
116	    const value = readTerm(name);
117	    const v2 = Number.isFinite(value) ? value : 0;
118	    weighted += weight * (v2 / per);
119	    covered += weight;
120	  }
121	  return covered === 0 ? null : weighted / covered;
122	}
