}

// Evaluate every rule over every subject.
//
//   subjectsOf(rule)       the subjects this rule judges, [{ id, pack, … }]
//   figureOf(subject, name, { previous, median, window })   a number, or null
//   predicateOf(subject, name)                              a boolean, or null
