    ...Object.keys(rule.floor ?? {}).map(parseAtom),
  ];
  for (const atom of atoms) {
    if (atom.value !== undefined) continue;
    const label = `${atom.previous ? 'previous.' : ''}${atom.median ? `median(${atom.name})` : atom.name}`;
