python3 - <<'PY'
import json,collections
p='packs/claudinite-growth/usage-rules.json'
d=json.load(open(p,object_pairs_hook=collections.OrderedDict))
# Thresholds: one measure, different bars by subject kind. The window this was
# calibrated from carried activity 453.
BARS={'check':120,'checks':120,'guard':90,'skill':60}
GLOBAL={'runs','sessions','previous.runs','previous.sessions'}
changed=[]
for r in d['rules']:
    if r['id']=='check-never-fires':
        r['and']='!proseTwin'
        r['finding']='never fires, and no RULES.md line states the same rule'
        changed.append('check-never-fires: and !proseTwin')
    if r['id']=='skill-adoption-not-reached':
        continue                      # its floor is scoped to the adoption window, not the repo's week
    nf=collections.OrderedDict()
    for name,need in r['floor'].items():
        if name in GLOBAL:
            key=('previous.activity' if name.startswith('previous.') else 'activity')
            nf[key]=BARS[r['over']]
            changed.append(f"{r['id']}: {name} {need} -> {key} {BARS[r['over']]}")
        else:
            nf[name]=need
    r['floor']=nf
open(p,'w').write(json.dumps(d,indent=2)+'\n')
for c in changed: print(c)
